<?php $this->assign('title', 'Manage pricing'); $this->Html->css('item-dialog', ['block'=>true]); ?>
<section class="page-heading"><h1>Manage pricing &amp; items</h1><p>Add, edit, or remove garments and discount rules.</p></section>
<section class="items-card"><h2>Garments</h2><table><tr><th>Item</th><th>Price</th><th>Description</th><th>Actions</th></tr><?php foreach ($items as $item): ?><tr><td><?= h($item->name) ?></td><td>$<?= number_format($item->unit_price_cents/100,2) ?></td><td><?= h($item->description ?: 'N/A') ?></td><td><button type="button" onclick="this.nextElementSibling.showModal()">Edit</button><dialog class="item-dialog"><?= $this->Form->create(null) ?><?= $this->Form->hidden('action',['value'=>'save_item']) ?><?= $this->Form->hidden('id',['value'=>$item->id]) ?><?= $this->Form->control('name',['value'=>$item->name]) ?><?= $this->Form->control('price',['type'=>'number','step'=>'0.01','value'=>$item->unit_price_cents/100]) ?><?= $this->Form->control('description',['value'=>$item->description]) ?><?= $this->Form->control('position',['type'=>'number','value'=>$item->position]) ?><?= $this->Form->control('active',['type'=>'checkbox','checked'=>$item->active]) ?><?= $this->Form->button('Save changes',['class'=>'button-primary']) ?><button type="button" class="cancel-add" onclick="this.closest('dialog').close()">Cancel</button><?= $this->Form->end() ?></dialog> <?= $this->Form->create(null,['style'=>'display:inline']) ?><?= $this->Form->hidden('action',['value'=>'delete_item']) ?><?= $this->Form->hidden('id',['value'=>$item->id]) ?><?= $this->Form->button('Delete',['class'=>'remove-row']) ?><?= $this->Form->end() ?></td></tr><?php endforeach; ?></table><h3>Add garment</h3><?= $this->Form->create() ?><?= $this->Form->hidden('action',['value'=>'save_item']) ?><?= $this->Form->control('name') ?><?= $this->Form->control('price',['type'=>'number','step'=>'0.01']) ?><?= $this->Form->control('description') ?><?= $this->Form->control('position',['type'=>'number','value'=>100]) ?><?= $this->Form->control('active',['type'=>'checkbox','checked'=>true]) ?><?= $this->Form->button('Save garment',['class'=>'button-primary']) ?><?= $this->Form->end() ?></section>
<section class="items-card"><h2>Discount rules</h2><table><tr><th>Rule</th><th>Value</th><th>Actions</th></tr><?php foreach ($rules as $rule): ?><tr><td><?= h($rule->name) ?></td><td><?= (int)$rule->discount_value ?><?= $rule->discount_type === 'percentage' ? '%' : ' cents' ?></td><td><button type="button" onclick="this.nextElementSibling.showModal()">Edit</button><dialog class="item-dialog"><?= $this->Form->create(null) ?><?= $this->Form->hidden('action',['value'=>'save_rule']) ?><?= $this->Form->hidden('id',['value'=>$rule->id]) ?><?= $this->Form->control('name',['value'=>$rule->name]) ?><?= $this->Form->control('minimum_item_count',['type'=>'number','value'=>$rule->minimum_item_count]) ?><?= $this->Form->control('discount_type',['options'=>['percentage'=>'Percentage','fixed'=>'Fixed cents'],'value'=>$rule->discount_type]) ?><?= $this->Form->control('discount_value',['type'=>'number','value'=>$rule->discount_value]) ?><?= $this->Form->button('Save changes',['class'=>'button-primary']) ?><button type="button" class="cancel-add" onclick="this.closest('dialog').close()">Cancel</button><?= $this->Form->end() ?></dialog> <?= $this->Form->create(null,['style'=>'display:inline']) ?><?= $this->Form->hidden('action',['value'=>'delete_rule']) ?><?= $this->Form->hidden('id',['value'=>$rule->id]) ?><?= $this->Form->button('Delete',['class'=>'remove-row']) ?><?= $this->Form->end() ?></td></tr><?php endforeach; ?></table><h3>Add discount rule</h3><?= $this->Form->create() ?><?= $this->Form->hidden('action',['value'=>'save_rule']) ?><?= $this->Form->control('name') ?><?= $this->Form->control('minimum_item_count',['type'=>'number']) ?><?= $this->Form->control('discount_type',['options'=>['percentage'=>'Percentage','fixed'=>'Fixed cents']]) ?><?= $this->Form->control('discount_value',['type'=>'number']) ?><?= $this->Form->button('Save discount rule',['class'=>'button-primary']) ?><?= $this->Form->end() ?></section>
